def create_farms_for_existing_sellers(apps, schema_editor):
    Farm = apps.get_model("companies", "Farm")
    EggSeller = apps.get_model("poultryitems", "EggSeller")
    ChickenSeller = apps.get_model("poultryitems", "ChickenSeller")
    database = schema_editor.connection.alias

    for seller in EggSeller.objects.using(database).filter(farm__isnull=True).iterator():
        farm, _ = Farm.objects.using(database).get_or_create(
            owner_id=seller.user_id,
            name=seller.farm_name,
            defaults={
                "city": seller.city,
                "country": seller.country,
                "address": seller.address,
                "phone": seller.phone,
                "email": seller.email,
            },
        )
        seller.farm_id = farm.pk
        seller.save(update_fields=("farm",), using=database)

    for seller in ChickenSeller.objects.using(database).filter(farm__isnull=True).iterator():
        farm, _ = Farm.objects.using(database).get_or_create(
            owner_id=seller.user_id,
            name=seller.farm_name,
            defaults={
                "city": seller.location,
                "phone": seller.contact_number,
                "email": seller.email,
            },
        )
        seller.farm_id = farm.pk
        seller.save(update_fields=("farm",), using=database)


